from pathlib import Path
import json
home=Path.home()
ids=['DEV-PRED-CONT-NEXT-1a89382dc23bab417facffc7','DEV-PRED-CONT-NEXT-7b8846e9669d7c05da627cc7','DEV-PRED-CONT-NEXT-50178168cc8b3a8e879648db','DEV-PRED-CONT-NEXT-9d4707f66ec86d580643a52c','DEV-PRED-ASTRA-RESULT-NORMALIZE-R6-20261008-N1E140']
parts=[]
for tid in ids:
  p=home/'.local/state/prediction-project-executor'/f'{tid}.json'
  parts.append('TASK='+tid)
  parts.append('STATE_EXISTS='+str(int(p.exists())))
  if p.exists():
    try:o=json.loads(p.read_text())
    except Exception as e:o={'error':'READ:'+type(e).__name__}
    for k in ['status','exit_code','error','detail','finished_at_utc','source_commit','worktree','branch']:
      if k in o: parts.append(k.upper()+'='+str(o.get(k)).replace('|','/').replace('\n',' ')[:4000])
print('ERROR_CLASS=NORMALIZE_CHAIN_STATUS_CONT')
print('ERROR='+'|'.join(parts))
raise SystemExit(1)
